fn sqlite_snapshot_allocation_real_native_bridge_settles_interior_failure_before_next_copy(){
    use semio_framework_value::NativeDecodeControl;use std::cell::Cell;
    let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🧮️allocation/🔣️.json")).unwrap();let b=&f["nativeBridge"];let n=|name:&str|b[name].as_u64().unwrap()as usize;let cancel=Cell::new(false);let interior=Cell::new(false);let mut callback=|p:SqliteSnapshotProgress|{let stop=cancel.get()&&p.phase==SqliteSnapshotPhase::DecodeNative&&p.completed>=n("cancelAt")&&p.completed<p.total;interior.set(interior.get()||stop);!stop};let mut control=SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits{max_allocation_bytes:n("maximumBytes"),max_value_bytes:0,..Default::default()});let source=vec![7u8;n("cancelBytes")];
    let success=control.allocation_stage(SqliteSnapshotPhase::ProjectSnapshot,|remaining,progress|{let mut callback=|p:semio_framework_value::native_decoding::NativeDecodeProgress|progress(p.completed,p.total);let mut native=NativeDecodeControl::new(remaining,&mut callback);let result=native.copy_bytes(&source[..n("successBytes")]);(result,native.owned_bytes())}).unwrap().unwrap();assert_eq!(success.len(),n("successBytes"));drop(success);cancel.set(true);
    let canceled=control.allocation_stage(SqliteSnapshotPhase::DecodeNative,|remaining,progress|{let mut callback=|p:semio_framework_value::native_decoding::NativeDecodeProgress|progress(p.completed,p.total);let mut native=NativeDecodeControl::new(remaining,&mut callback);let result=native.copy_bytes(&source);(result,native.owned_bytes())}).unwrap();assert!(canceled.is_err());assert!(interior.get());assert_eq!(control.allocation_remaining_bytes(),n("remainingAfterCancellation"));cancel.set(false);
    let refused=control.allocation_stage(SqliteSnapshotPhase::ReconstructSnapshot,|remaining,progress|{let mut callback=|p:semio_framework_value::native_decoding::NativeDecodeProgress|progress(p.completed,p.total);let mut native=NativeDecodeControl::new(remaining,&mut callback);let result=native.copy_bytes(&source[..n("refusedBytes")]);assert_eq!(native.owned_bytes(),0,"next producer must refuse before owning its output buffer");(result,native.owned_bytes())}).unwrap();assert!(refused.is_err());assert_eq!(control.allocation_remaining_bytes(),n("remainingAfterCancellation"));control.check_value_bytes(0).unwrap();
}

